{"task": "rename-amount", "steps": [
  {"note": "Expand: create the trigger function that keeps amount and total in sync (whichever one a writer leaves NULL is copied from the other).",
   "sql": "CREATE OR REPLACE FUNCTION orders_sync_amount_total() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.total IS NULL THEN NEW.total := NEW.amount;
    ELSIF NEW.amount IS NULL THEN NEW.amount := NEW.total;
    END IF;
  ELSIF NEW.amount IS DISTINCT FROM OLD.amount AND NEW.total IS NOT DISTINCT FROM OLD.total THEN
    NEW.total := NEW.amount;
  ELSIF NEW.total IS DISTINCT FROM OLD.total AND NEW.amount IS NOT DISTINCT FROM OLD.amount THEN
    NEW.amount := NEW.total;
  END IF;
  RETURN NEW;
END $$;"},

  {"note": "Expand: add nullable total (metadata-only) and the sync trigger in one transaction. Short lock_timeout with retries so we never queue app queries behind a waiting ACCESS EXCLUSIVE lock.",
   "sql": "DO $$
BEGIN
  PERFORM set_config('lock_timeout', '200ms', true);
  FOR i IN 1..150 LOOP
    BEGIN
      ALTER TABLE orders ADD COLUMN total numeric(10,2);
      CREATE TRIGGER orders_sync_amount_total BEFORE INSERT OR UPDATE ON orders
        FOR EACH ROW EXECUTE FUNCTION orders_sync_amount_total();
      RETURN;
    EXCEPTION WHEN lock_not_available THEN
      PERFORM pg_sleep(0.3);
    END;
  END LOOP;
  RAISE EXCEPTION 'could not lock orders to add total';
END $$;"},

  {"note": "Backfill total from amount in 20k-row id batches, committing each batch (short row locks, no long transaction). Rows above the max id seen here were inserted after the trigger existed, so already have total.",
   "sql": "DO $$
DECLARE
  lo bigint := 0;
  maxid bigint;
  batch constant bigint := 20000;
BEGIN
  SELECT coalesce(max(id), 0) INTO maxid FROM orders;
  WHILE lo <= maxid LOOP
    UPDATE orders SET total = amount WHERE id >= lo AND id < lo + batch AND total IS NULL;
    COMMIT;
    lo := lo + batch;
  END LOOP;
END $$;"},

  {"note": "Prepare NOT NULL on total: add a NOT VALID check constraint (brief lock, no scan), with lock retries.",
   "sql": "DO $$
BEGIN
  PERFORM set_config('lock_timeout', '200ms', true);
  FOR i IN 1..150 LOOP
    BEGIN
      ALTER TABLE orders ADD CONSTRAINT orders_total_not_null CHECK (total IS NOT NULL) NOT VALID;
      RETURN;
    EXCEPTION WHEN lock_not_available THEN
      PERFORM pg_sleep(0.3);
    END;
  END LOOP;
  RAISE EXCEPTION 'could not lock orders to add check constraint';
END $$;"},

  {"note": "Validate the check constraint: full scan under SHARE UPDATE EXCLUSIVE, which does not block reads or writes. Fails (and stops the plan) if any row still has a NULL total.",
   "sql": "ALTER TABLE orders VALIDATE CONSTRAINT orders_total_not_null;"},

  {"note": "Make total NOT NULL. Postgres uses the validated check constraint to skip the table scan, so the lock is brief; then drop the now-redundant check.",
   "sql": "DO $$
BEGIN
  PERFORM set_config('lock_timeout', '200ms', true);
  FOR i IN 1..150 LOOP
    BEGIN
      ALTER TABLE orders ALTER COLUMN total SET NOT NULL;
      ALTER TABLE orders DROP CONSTRAINT orders_total_not_null;
      RETURN;
    EXCEPTION WHEN lock_not_available THEN
      PERFORM pg_sleep(0.3);
    END;
  END LOOP;
  RAISE EXCEPTION 'could not lock orders to set total NOT NULL';
END $$;"},

  {"note": "Switch the app to total. During the rolling update old pods write amount and new pods write total; the trigger fills the other column, so both versions keep working.",
   "deploy": {"AMOUNT_READ": "total", "AMOUNT_WRITE": "total"}},

  {"note": "Give terminating old pods time to drain and exit (they close connections after ~3 s; grace period is 30 s).",
   "wait": 35},

  {"note": "Contract: first wait until no client session's last query still uses amount (old app version), failing safely if one remains; then drop the trigger and the amount column in one transaction with lock retries, and drop the function.",
   "sql": "DO $$
DECLARE
  old_sessions int;
BEGIN
  FOR i IN 1..120 LOOP
    PERFORM pg_stat_clear_snapshot();
    SELECT count(*) INTO old_sessions FROM pg_stat_activity
     WHERE datname = current_database() AND pid <> pg_backend_pid() AND backend_type = 'client backend'
       AND (position('customer_id, amount, status' IN query) > 0 OR position('amount AS amount' IN query) > 0);
    EXIT WHEN old_sessions = 0;
    PERFORM pg_sleep(1);
  END LOOP;
  IF old_sessions > 0 THEN
    RAISE EXCEPTION '% session(s) of the old app version still use amount; not dropping it', old_sessions;
  END IF;
  PERFORM set_config('lock_timeout', '200ms', true);
  FOR i IN 1..150 LOOP
    BEGIN
      DROP TRIGGER orders_sync_amount_total ON orders;
      ALTER TABLE orders DROP COLUMN amount;
      DROP FUNCTION orders_sync_amount_total();
      RETURN;
    EXCEPTION WHEN lock_not_available THEN
      PERFORM pg_sleep(0.3);
    END;
  END LOOP;
  RAISE EXCEPTION 'could not lock orders to drop amount';
END $$;"}
]}
